GRAU_TEXTO = {'a': 'Lei expressa ou tese pacificada', 'b': 'Jurisprudência favorável sem lei expressa', 'c': 'Tese controvertida'}

def fundamentar(achado):
    f, g = FUNDAMENTACAO.get(achado.get('regra', ''), ('Verificar dispositivo.', 'c'))
    achado.setdefault('fundamentacao', f)
    achado.setdefault('tese', GRAU_TEXTO[g])
    return achado
